use serde_json::{Value, from_str};
use std::cmp::Ordering;

pub fn solve(input: Value) -> Value {
    let pairs: Vec<(i64, i64)> = input.as_array()
        .unwrap()
        .iter()
        .map(|v| {
            let pair: Vec<i64> = v.as_array()
                .unwrap()
                .iter()
                .map(|n| n.as_i64().unwrap())
                .collect();
            (pair[0], pair[1])
        })
        .collect();

    let mut sorted_pairs = pairs.clone();
    sorted_pairs.sort_by(|a, b| {
        match b.0.cmp(&a.0) {
            Ordering::Equal => a.1.cmp(&b.1),
            other => other,
        }
    });

    Value::Array(sorted_pairs.into_iter().map(|(_, id)| id).collect())
}
